import { test } from 'node:test'
import assert from 'node:assert/strict'
// Tests execute the compiled output; dist is generated by yarn test.
// eslint-disable-next-line n/no-unpublished-import
import { buildMsc, MscOutput } from '../dist/core/msc.js'
const go = { command: 'go', cue: '', cuelist: '' }
const settings = { mscEnabled: true, midiPort: 'Vista', deviceId: 1, commandFormat: 1 }

test('GO matches Vista TBJLT196 published examples byte for byte', () => {
	assert.deepEqual(buildMsc(settings, go), [0xf0, 0x7f, 1, 2, 1, 1, 0xf7])
	assert.deepEqual(
		buildMsc(settings, { ...go, cue: '34.5', cuelist: '12' }),
		[0xf0, 0x7f, 1, 2, 1, 1, 0x33, 0x34, 0x2e, 0x35, 0, 0x31, 0x32, 0xf7],
	)
	assert.deepEqual(
		buildMsc(settings, { ...go, cue: '123.45' }),
		[0xf0, 0x7f, 1, 2, 1, 1, 0x31, 0x32, 0x33, 0x2e, 0x34, 0x35, 0xf7],
	)
})
test('STOP and RESUME, device ID and command format', () => {
	assert.deepEqual(buildMsc({}, { ...go, command: 'stop' }), [240, 127, 1, 2, 1, 2, 247])
	assert.deepEqual(
		buildMsc({ deviceId: 127, commandFormat: 127 }, { ...go, command: 'resume', cue: '01.20', cuelist: '3' }),
		[240, 127, 127, 2, 127, 3, 48, 49, 46, 50, 48, 0, 51, 247],
	)
	assert.equal(buildMsc({ deviceId: 0 }, go)[2], 0)
})
test('reject malformed addresses, missing cue, invalid commands and non-7-bit settings', () => {
	for (const value of ['1\u00002', 'é', '1..2', '-1', '1e2', '1,2', '.5', '5.']) {
		assert.throws(() => buildMsc(settings, { ...go, cue: value }))
		assert.throws(() => buildMsc(settings, { ...go, cue: '1', cuelist: value }))
	}
	assert.throws(() => buildMsc(settings, { ...go, cuelist: '12' }))
	assert.throws(() => buildMsc(settings, { ...go, command: 'load' }))
	for (const value of [-1, 128, 1.5, NaN, Infinity]) {
		assert.throws(() => buildMsc({ deviceId: value }, go))
		assert.throws(() => buildMsc({ commandFormat: value }, go))
	}
})
function fixture(names = ['Other', 'Vista']) {
	const instances = []
	const client = new MscOutput(() => {
		const output = {
			opened: [],
			messages: [],
			closed: 0,
			getPortCount: () => names.length,
			getPortName: (i) => names[i],
			openPort(i) {
				this.opened.push(i)
			},
			closePort() {
				this.closed++
			},
			sendMessage(message) {
				this.messages.push(message)
			},
		}
		instances.push(output)
		return output
	})
	return { client, instances, names }
}
test('enumerates ports, selects exact name, sends, reconfigures and closes', () => {
	const { client, instances, names } = fixture()
	assert.deepEqual(client.ports(), names)
	assert.equal(instances[0].closed, 1)
	client.configure(settings)
	assert.deepEqual(instances[1].opened, [1])
	client.send(go)
	assert.deepEqual(instances[1].messages, [[240, 127, 1, 2, 1, 1, 247]])
	names.reverse()
	client.configure(settings)
	assert.equal(instances[1].closed, 1)
	assert.deepEqual(instances[2].opened, [0])
	client.configure({})
	assert.equal(instances[2].closed, 1)
	assert.throws(() => client.send(go), /disabled/)
	client.close()
})
test('missing or duplicate port never falls back to another device', () => {
	for (const names of [[], ['Other'], ['Vista', 'Vista']]) {
		const { client, instances } = fixture(names)
		assert.throws(() => client.configure(settings), /uniquely/)
		assert.deepEqual(instances[0].opened, [])
		assert.equal(instances[0].closed, 1)
		assert.throws(() => client.send(go))
	}
})
test('open/send errors release output; bad action data never sends', () => {
	const { client, instances } = fixture()
	client.configure(settings)
	assert.throws(() => client.send({ ...go, cue: 'invalid' }))
	assert.equal(instances[0].messages.length, 0)
	instances[0].sendMessage = () => {
		throw new Error('Disconnected')
	}
	assert.throws(() => client.send(go), /Disconnected/)
	assert.equal(instances[0].closed, 1)
	assert.throws(() => client.send(go), /unavailable/)
	const failed = new MscOutput(() => ({
		...instances[0],
		openPort() {
			throw new Error('Busy')
		},
	}))
	assert.throws(() => failed.configure(settings), /Busy/)
})
